import React, { useEffect, useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { ArrowLeft, Bell } from "lucide-react";
import { h } from "./h";
import { useNotifications } from "./NotificationContext";
import { Button } from "./ui";

function fmtTime(iso) {
  if (!iso) return "";
  try {
    const d = new Date(iso);
    return d.toLocaleString(undefined, { dateStyle: "medium", timeStyle: "short" });
  } catch {
    return "";
  }
}

export function NotificationBell({ to, onAdminOpen, className }) {
  const { unreadCount, refresh } = useNotifications();
  const nav = useNavigate();

  return h(
    "button",
    {
      type: "button",
      title: unreadCount > 0 ? `Notifications (${unreadCount} unread)` : "Notifications",
      "aria-label": unreadCount > 0 ? `Notifications, ${unreadCount} unread` : "Notifications",
      className:
        className ||
        `relative inline-flex shrink-0 items-center gap-1 rounded-full border border-white/15 bg-white/50 px-2 py-1.5 text-[11px] font-medium transition hover:bg-white/70 dark:bg-white/5 dark:hover:bg-white/10 sm:px-2.5 sm:text-xs`,
      onClick: () => {
        void refresh();
        if (typeof onAdminOpen === "function") {
          onAdminOpen();
          return;
        }
        if (to) nav(to);
      }
    },
    [
      h(Bell, { key: "i", className: "h-3.5 w-3.5 shrink-0 sm:h-4 sm:w-4" }),
      unreadCount > 0
        ? h(
            "span",
            {
              key: "b",
              className:
                "ml-0.5 flex h-4 min-w-[1rem] items-center justify-center rounded-full bg-rose-500 px-1 text-[10px] font-bold text-white sm:h-5 sm:min-w-[1.25rem] sm:text-xs"
            },
            unreadCount > 99 ? "99+" : String(unreadCount)
          )
        : null
    ].filter(Boolean)
  );
}

export function NotificationsPage({
  ordersLink = "/orders",
  backLink = "/",
  backLabel = "Back",
  embedded
}) {
  const { loadList, markRead, markAllRead, loading } = useNotifications();
  const [items, setItems] = useState([]);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      const list = await loadList();
      if (!cancelled) setItems(list);
    })();
    return () => {
      cancelled = true;
    };
  }, [loadList]);

  return h("div", {
    className: embedded
      ? "mx-auto max-w-2xl space-y-3"
      : "mx-auto max-w-2xl space-y-4 px-4 py-8 sm:px-6"
  }, [
    h("div", { key: "top", className: "flex flex-wrap items-center justify-between gap-3" }, [
      embedded
        ? h("span", { key: "sp" })
        : h(
            Link,
            {
              key: "bk",
              to: backLink,
              className:
                "inline-flex items-center gap-1.5 text-sm font-medium text-slate-600 hover:text-slate-900 dark:text-slate-400 dark:hover:text-white"
            },
            [h(ArrowLeft, { key: "i", className: "h-4 w-4" }), backLabel]
          ),
      h(
        Button,
        {
          key: "all",
          type: "button",
          variant: "ghost",
          className: "!text-xs",
          onClick: async () => {
            await markAllRead();
            setItems(await loadList());
          }
        },
        "Mark all read"
      )
    ]),
    embedded
      ? null
      : h("h1", { key: "h", className: "font-display text-2xl font-bold text-slate-900 dark:text-white" }, "Notifications"),
    loading
      ? h("p", { key: "ld", className: "text-sm text-slate-500" }, "Loading…")
      : null,
    items.length === 0 && !loading
      ? h(
          "p",
          {
            key: "em",
            className:
              "rounded-2xl border border-dashed border-slate-300/80 bg-white/50 p-8 text-center text-sm text-slate-600 dark:border-white/10 dark:bg-white/5 dark:text-slate-400"
          },
          "No notifications yet."
        )
      : h(
          "ul",
          { key: "list", className: "space-y-2" },
          items.map((n) =>
            h(
              "li",
              {
                key: n.id,
                className: `rounded-2xl border p-4 transition ${
                  n.read
                    ? "border-slate-200/90 bg-white/40 dark:border-white/10 dark:bg-white/5"
                    : "border-sky-300/40 bg-sky-50/80 dark:border-sky-500/25 dark:bg-sky-950/30"
                }`
              },
              [
                h("div", { key: "r", className: "flex flex-wrap items-start justify-between gap-2" }, [
                  h("div", { key: "m", className: "min-w-0 flex-1" }, [
                    h("p", { className: "font-semibold text-slate-900 dark:text-white" }, n.title || n.type),
                    h("p", { className: "mt-1 text-sm text-slate-600 dark:text-slate-300" }, n.message),
                    n.orderId && ordersLink
                      ? h(
                          Link,
                          {
                            key: "ol",
                            to: `${ordersLink}?openOrder=${encodeURIComponent(n.orderId)}`,
                            className: "mt-2 inline-block text-xs font-medium text-sky-600 hover:underline dark:text-sky-300"
                          },
                          "View order →"
                        )
                      : null
                  ]),
                  h("span", { key: "t", className: "shrink-0 text-xs text-slate-500" }, fmtTime(n.createdAt))
                ]),
                !n.read
                  ? h(
                      "div",
                      { key: "a", className: "mt-3" },
                      h(
                        Button,
                        {
                          type: "button",
                          variant: "ghost",
                          className: "!h-8 !min-h-0 !px-3 !text-xs",
                          onClick: async () => {
                            await markRead(n.id);
                            setItems(await loadList());
                          }
                        },
                        "Mark read"
                      )
                    )
                  : null
              ].filter(Boolean)
            )
          )
        )
  ]);
}
